export async function resolve_env(key: key): Promise<raw> {
  if (is(key, 'literal')) {
    return key
  } else {
    let env_var = key.env

    let current_env = deserialize(read(env_file))

    let raw = current_env[env_var]

    if (is(raw, 'absent')) {
      throw err(`env ${env_var} should exist`)
    }

    return raw
  }
