          prompt_tokens,
          completion_tokens,
          total_tokens,
        }
      }
    }
  }

  // Flush any remaining decoder data
  buffer += decoder.decode()

  finish(complete())

  function fail(
    type: 'network' | 'endpoint',
    message: string,
    payload = response,
  ) {
    end_time = monotonic()

    return {
      has_failed: true,
      role: 'assistant' as const,
      content:
        content +
        '\n```chat_error\n' +
        serialize({
          type,
          message,
          payload,
        }) +
        '```\n',
      start_time,
      end_time,
      model,
    }
  }

  function complete() {
    end_time = monotonic()

    let duration = end_time - (first_append_time ?? start_time)

    let perf = {
      tokens_per_second: (usage?.total_tokens ?? 0) / duration,
      time_to_first_token: first_append_time - start_time,
    }

    // parse tools

    return {
      role: 'assistant' as const,
      content,
      reasoning,
      start_time,
      end_time,
      usage,
      perf,
      model,
    }
  }

  return stream_text
}

export async function generate_mock(
  { context, endpoint, model, key },
