export function structure(component = 'app', tag = 'div') {  
  return new Proxy(
    {},
    {
      get(_, prop) {
        const class_name = `${component}_${prop}`

        return (...args) => {
          const { props, children } = parse(...args)

          if (has(props, 'className')) {
            props.className += ` ${class_name}`
          } else {
            props.className = class_name
          } 

          return h(tag, props, ...children)
        }
      },
    },
  )
}

